CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_FIELD_SERVICE_DAY_SEGMENT_VISIT_TYPE
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_FIELD_SERVICE at grain Date.FiscalYear, Date.FullDate, Date.Quarter, Customer.CustomerSegment, FieldService.VisitType; covers 10.93% of weighted demand (1 clusters); est. 88,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.FULL_DATE,
       d1.QUARTER,
       c2.CUSTOMER_SEGMENT,
       f.VISIT_TYPE,
       SUM(f.DURATION) AS DURATION,
       COUNT(*) AS FIELD_SERVICE_COUNT
FROM CORE.FCT_FIELD_SERVICE f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_CUSTOMER c2 ON f.CUSTOMER_ID = c2.CUSTOMER_ID
GROUP BY ALL;
